import { BrowserRouter as Router, Routes, Route } from 'react-router-dom'
import HeroShowcase from './pages/HeroShowcase'

function App() {
  return (
    <Router>
      <Routes>
        {/* Portfolio home */}
        <Route path="/" element={<Home />} />

        {/* Marvel Rivals project */}
        <Route path="/marvel-rivals" element={<HeroShowcase />} />
      </Routes>
    </Router>
  )
}

export default App
